DROP TABLE IF EXISTS `menuitem`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `menuitem` (
  `MenuItemID` bigint(20) NOT NULL AUTO_INCREMENT,
  `RestaurantID` bigint(20) NOT NULL,
  `BranchID` bigint(20) DEFAULT NULL COMMENT 'NULL: món toàn chu?i, NOT NULL: món riêng chi nhánh',
  `CategoryID` bigint(20) NOT NULL,
  `Name` varchar(255) NOT NULL,
  `Unit` varchar(50) NOT NULL DEFAULT 'Phần',
  `Description` longtext DEFAULT NULL,
  `BasePrice` decimal(18,2) NOT NULL,
  `url_Image` varchar(500) DEFAULT NULL,
  `IsActive` tinyint(4) NOT NULL DEFAULT 1,
  `IsWeightBased` tinyint(4) NOT NULL DEFAULT 0,
  `CreatedAt` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`MenuItemID`),
  UNIQUE KEY `UQ_MenuItem` (`RestaurantID`,`Name`),
  KEY `FK_MenuItem_Category` (`CategoryID`),
  KEY `FK_MenuItem_Branch` (`BranchID`),
  KEY `idx_menuitem_branch` (`RestaurantID`,`BranchID`,`IsActive`),
  CONSTRAINT `FK_MenuItem_Branch` FOREIGN KEY (`BranchID`) REFERENCES `branch` (`BranchID`) ON DELETE CASCADE,
  CONSTRAINT `FK_MenuItem_Category` FOREIGN KEY (`CategoryID`) REFERENCES `category` (`CategoryID`),
  CONSTRAINT `FK_MenuItem_Restaurant` FOREIGN KEY (`RestaurantID`) REFERENCES `restaurant` (`RestaurantID`)
) ENGINE=InnoDB AUTO_INCREMENT=32 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

