INSERT INTO `menuitem` VALUES (1,1,NULL,1,'Bò Tảng Mỹ nướng đá','Phần','Thăn bò Mỹ nguyên tảng nướng xèo xèo trên đá nóng giữ trọn vị ngọt mềm mọng nước.',250000.00,'https://images.unsplash.com/photo-1558030137-a56c1b004fa3?w=600&auto=format&fit=crop&q=80',1,0,'2026-10-09 02:46:12'),(2,1,NULL,1,'Ba chỉ heo cuộn nấm','Phần','Ba chỉ heo tươi thái lát cuộn nấm kim châm nướng vàng giòn, thơm béo hấp dẫn.',120000.00,'https://images.unsplash.com/photo-1529193591184-b1d58069ecdd?w=600&auto=format&fit=crop&q=80',1,0,'2026-10-09 02:46:12'),(3,1,NULL,2,'Mực lá khổng lồ','Kg','Mực lá đại dương tươi sống dày thịt, giòn ngọt tự nhiên, cân theo khối lượng thực tế.',450000.00,'https://images.unsplash.com/photo-1599487488170-d11ec9c172f0?w=600&auto=format&fit=crop&q=80',1,1,'2026-10-09 02:46:12'),(4,1,NULL,3,'Coca Cola','Lon','Lon Coca-Cola ướp lạnh sảng khoái, giải ngấy tuyệt vời cho bữa tiệc nướng BBQ.',25000.00,'https://images.unsplash.com/photo-1554866585-cd94860890b7?w=600&auto=format&fit=crop&q=80',1,0,'2026-10-09 02:46:12'),(5,1,NULL,1,'Dẻ sườn bò Mỹ sốt Galbi','Phần','Dẻ sườn bò Mỹ ướp sốt Galbi truyền thống Hàn Quốc ngọt thanh, mềm mọng khi nướng than hoa.',260000.00,'https://images.unsplash.com/photo-1544025162-d76694265947?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(6,1,NULL,1,'Ba chỉ bò Mỹ cuộn nấm kim châm','Phần','Thịt ba chỉ bò Mỹ vân mỡ đều, cuộn nấm kim châm giòn ngọt, chấm sốt tương đậu đậm đà.',165000.00,'https://images.unsplash.com/photo-1558030006-450675393462?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(7,1,NULL,1,'Lõi vai bò Wagyu sốt tiêu đen','Phần','Bò Wagyu thượng hạng vân cẩm thạch mềm tan, hòa quyện sốt tiêu đen Phú Quốc thơm lừng.',380000.00,'https://images.unsplash.com/photo-1546964124-0cce460f38ef?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(8,1,NULL,1,'Thăn nội bò Úc sốt bơ tỏi','Phần','Phần thăn mềm nhất của bò Úc tươi, phục vụ kèm bơ tỏi béo ngậy nướng xèo xèo trên vỉ.',290000.00,'https://images.unsplash.com/photo-1600891964599-f61ba0e24092?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(9,1,NULL,1,'Gầu bò Mỹ sốt tare','Phần','Gầu bò giòn sần sật với tỷ lệ nạc mỡ hoàn hảo, ướp sốt tare Nhật Bản mặn ngọt hài hòa.',175000.00,'https://images.unsplash.com/photo-1504973960431-1c467e159aa4?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(10,1,NULL,1,'Sườn sụn heo sốt cay Hàn Quốc','Phần','Sườn sụn heo giòn rụm ướp sốt gochujang cay nồng đặc trưng phong cách Seoul.',145000.00,'https://images.unsplash.com/photo-1529193591184-b1d58069ecdd?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(11,1,NULL,1,'Má heo nướng muối ớt xanh','Phần','Má heo nạc giòn mềm, ướp muối ớt xiêm rừng thơm cay the hấp dẫn.',155000.00,'https://images.unsplash.com/photo-1544025162-d76694265947?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(12,1,NULL,1,'Lòng non heo nướng giòn sốt cay','Phần','Món nhắm nướng BBQ kinh điển, giòn dai béo ngậy chấm cùng muối tiêu chanh.',135000.00,'https://images.unsplash.com/photo-1555939594-58d7cb561ad1?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(13,1,NULL,2,'Tôm càng xanh nướng muối ớt','Phần','Tôm càng xanh tươi sống thịt chắc ngọt, muối ớt cay đậm đà.',280000.00,'https://images.unsplash.com/photo-1565680018434-b513d5e5fd47?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(14,1,NULL,2,'Bạch tuộc nướng sa tế cay','Phần','Bạch tuộc đại dương giòn sần sật ướp sốt sa tế tôm cay bùng nổ vị giác.',165000.00,'https://images.unsplash.com/photo-1541544741938-0af808871cc0?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(15,1,NULL,2,'Hàu sữa nướng phô mai kéo sợi','Phần','Hàu sữa Pháp tươi béo ngậy phủ lớp phô mai Mozzarella kéo sợi vàng ươm.',135000.00,'https://images.unsplash.com/photo-1532550907401-a500c9a57435?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(16,1,NULL,2,'Cá hồi Na Uy nướng bơ chanh','Kg','Phi lê cá hồi Na Uy tươi nguyên miếng, cân theo khối lượng và phục vụ sốt bơ chanh thảo mộc.',320000.00,'https://images.unsplash.com/photo-1519708227418-c8fd9a32b7a2?w=500&auto=format&fit=crop&q=60',1,1,'2026-10-13 20:13:29'),(17,1,NULL,2,'Sò điệp Nhật nướng mỡ hành','Phần','Sò điệp Hokkaido cùi dày ngọt lịm, nướng mỡ hành thơm lừng rắc đậu phộng rang giòn.',190000.00,'https://images.unsplash.com/photo-1615141982883-c7ad0e69fd62?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(18,1,NULL,3,'Pepsi Black Chanh Không Calo','Lon','Nước ngọt có ga vị chanh thanh mát, 0 calo không lo tăng cân khi ăn thịt nướng.',25000.00,'https://images.unsplash.com/photo-1622483767028-3f66f32aef97?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(19,1,NULL,3,'Sprite Chanh Bạc Hà ướp lạnh','Lon','Nước ngọt có ga vị chanh bạc hà sảng khoái cực độ.',25000.00,'https://images.unsplash.com/photo-1625772299848-391b6a87d7b3?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(20,1,NULL,3,'Trà đào cam sả hạt chia','Ly','Trà thảo mộc cam sả kết hợp đào giòn chua ngọt thanh mát, hạt chia giàu dinh dưỡng.',45000.00,'https://images.unsplash.com/photo-1556679343-c7306c1976bc?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(21,1,NULL,3,'Trà mận Hà Nội đá xay','Ly','Mận hậu ngâm cốt trà đậm đà, đá xay mát rượi giải ngấy thịt nướng tuyệt hảo.',48000.00,'https://images.unsplash.com/photo-1544787219-7f47ccb76574?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(22,1,NULL,3,'Trà ổi hồng chanh dây','Ly','Sự kết hợp giữa ổi hồng thơm ngát và chanh dây chua dịu, màu hồng quyến rũ.',45000.00,'https://images.unsplash.com/photo-1513558161293-cdaf765ed2fd?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(23,1,NULL,3,'Nước ép dưa hấu nguyên chất','Ly','100% dưa hấu tươi ép lạnh không đường, ngọt mát tự nhiên giải nhiệt tức thì.',42000.00,'https://images.unsplash.com/photo-1589733955941-5eeaf752f6dd?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(24,1,NULL,3,'Bia Tiger Bạc ướp lạnh','Lon','Bia Tiger Crystal ướp lạnh sâu, êm đằm sảng khoái nâng tầm bàn tiệc BBQ.',32000.00,'https://images.unsplash.com/photo-1608270586620-248524c67de9?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(25,1,NULL,3,'Bia Heineken Silver','Lon','Heineken Silver hương vị nhẹ êm, thiết kế sang trọng.',38000.00,'https://images.unsplash.com/photo-1608270586620-248524c67de9?w=600&auto=format&fit=crop&q=80',1,0,'2026-10-13 20:13:29'),(26,1,NULL,3,'Bia thủ công IPA Hoppy BBQ','Ly','Bia craft thủ công vị đắng hoa bia IPA thơm ngát mùi cam bưởi nhiệt đới.',68000.00,'https://images.unsplash.com/photo-1535958636474-b021ee887b13?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(27,1,NULL,3,'Soju Chamisul vị dâu tây','Chai','Rượu Soju Hàn Quốc ngọt dịu thơm mùi dâu tây chín mọng, uống cực êm.',85000.00,'https://images.unsplash.com/photo-1563227812-0ea4c22e6cc8?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(28,1,NULL,3,'Soju Chum Churum truyền thống','Chai','Soju truyền thống 16.9 độ dịu nhẹ chuẩn vị nướng đường phố Hàn Quốc.',80000.00,'https://images.unsplash.com/photo-1527061011665-3652c757a4d4?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(29,1,NULL,3,'Rượu mơ Choya Nhật Bản','Chai','Rượu mơ ngâm nguyên trái hảo hạng, vị chua ngọt thanh tao quý phái.',195000.00,'https://images.unsplash.com/photo-1569529465841-dfecdab7503b?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(30,1,NULL,3,'Rượu gạo Makgeolli men sống','Chai','Rượu gạo truyền thống màu trắng sữa, sủi bọt tăm êm dịu, rất hợp ăn cùng đồ nướng cay.',110000.00,'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=500&auto=format&fit=crop&q=60',1,0,'2026-10-13 20:13:29'),(31,1,NULL,3,'Nước khoáng thiên nhiên Dasani','Chai','Nước tinh khiết đóng chai 500ml ướp lạnh.',15000.00,'https://images.unsplash.com/photo-1560023907-5f339617ea30?w=600&auto=format&fit=crop&q=80',1,0,'2026-10-13 20:13:29');
