--
-- Table structure for table `order`
--

DROP TABLE IF EXISTS `order`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `order` (
  `OrderID` bigint(20) NOT NULL AUTO_INCREMENT,
  `SessionID` bigint(20) NOT NULL,
  `ParticipantID` bigint(20) NOT NULL,
  `OrderNumber` varchar(50) NOT NULL,
  `CreatedByStaffID` bigint(20) DEFAULT NULL,
  `Status` tinyint(4) NOT NULL,
  `CreatedAt` datetime NOT NULL DEFAULT current_timestamp(),
  `UpdatedAt` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`OrderID`),
  KEY `FK_Order_Participant` (`ParticipantID`),
  KEY `FK_Order_Session` (`SessionID`),
  KEY `FK_Order_Staff` (`CreatedByStaffID`),
  CONSTRAINT `FK_Order_Participant` FOREIGN KEY (`ParticipantID`) REFERENCES `sessionparticipant` (`ParticipantID`),
  CONSTRAINT `FK_Order_Session` FOREIGN KEY (`SessionID`) REFERENCES `session` (`SessionID`),
  CONSTRAINT `FK_Order_Staff` FOREIGN KEY (`CreatedByStaffID`) REFERENCES `staff` (`StaffID`)
) ENGINE=InnoDB AUTO_INCREMENT=752 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

