  `SessionID` bigint(20) NOT NULL,
  `MenuItemID` bigint(20) NOT NULL,
  `ParticipantID` bigint(20) DEFAULT NULL,
  `GuestName` varchar(100) DEFAULT NULL,
  `Quantity` int(11) NOT NULL DEFAULT 1,
  `Note` varchar(255) DEFAULT NULL,
  `CreatedAt` datetime NOT NULL DEFAULT current_timestamp(),
  `UpdatedAt` datetime NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`CartItemID`),
  KEY `fk_cart_participant` (`ParticipantID`),
  KEY `idx_cart_session` (`SessionID`),
  KEY `idx_cart_menuitem` (`MenuItemID`),
  CONSTRAINT `fk_cart_menuitem` FOREIGN KEY (`MenuItemID`) REFERENCES `menuitem` (`MenuItemID`) ON DELETE CASCADE,
  CONSTRAINT `fk_cart_participant` FOREIGN KEY (`ParticipantID`) REFERENCES `sessionparticipant` (`ParticipantID`) ON DELETE SET NULL,
  CONSTRAINT `fk_cart_session` FOREIGN KEY (`SessionID`) REFERENCES `session` (`SessionID`) ON DELETE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=20 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
